import java.util.*;

class Solution {
    public int maximumSubarraySum(int[] nums, int k) {
        Map<Integer, Integer> count = new HashMap<>();
        int sum = 0, best = 0; // at most 10^4 * 10^4, fits in int
        for (int i = 0; i < nums.length; i++) {
            sum += nums[i];
            count.merge(nums[i], 1, Integer::sum);
            if (i >= k) {                              // drop the element leaving the window
                int out = nums[i - k];
                sum -= out;
                if (count.merge(out, -1, Integer::sum) == 0) count.remove(out);
            }
            if (i >= k - 1 && count.size() == k) best = Math.max(best, sum);
        }
        return best;
    }
}

