class Solution:
    def maximumSubarraySum(self, nums: List[int], k: int) -> int:
        cnt = Counter(); s = 0; best = 0
        for i, x in enumerate(nums):
            cnt[x] += 1; s += x
            if i >= k:
                y = nums[i - k]; cnt[y] -= 1; s -= y
                if cnt[y] == 0: del cnt[y]
            if i >= k - 1 and len(cnt) == k: best = max(best, s)
        return best

