function maximumSubarraySum(nums, k) {
  let best = 0;
  for (let i = 0; i + k <= nums.length; i++) {
    const seen = new Set(); let s = 0, ok = true;
    for (let j = i; j < i + k; j++) { if (seen.has(nums[j])) { ok = false; break; } seen.add(nums[j]); s += nums[j]; }
    if (ok) best = Math.max(best, s);
  }
  return best;
}
